export declare const GITHUB_PANEL_CSS = "\n.dsh-github-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  height: 100%;\n  cursor: pointer;\n  color: var(--dsw-alias-label-secondary, #8c8c8c);\n  transition: color 0.15s ease;\n}\n.dsh-github-icon:hover {\n  color: var(--dsw-alias-label-primary, #ffffff);\n}\n.dsh-github-icon svg {\n  width: 18px;\n  height: 18px;\n  fill: currentColor;\n}\n\n/* \u4E3B\u9762\u677F\u5BB9\u5668 */\n.dsh-github-panel {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n  height: 100%;\n  overflow-y: auto;\n  padding: 24px 32px;\n  box-sizing: border-box;\n  background: var(--dsw-alias-bg-primary, #1e1e20);\n  color: var(--dsw-alias-label-primary, #ececec);\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n}\n\n/* \u9876\u90E8\u6807\u9898\u4E0E\u5DE5\u5177\u680F */\n.dsh-github-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 24px;\n  padding-bottom: 16px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, #333336);\n}\n.dsh-github-title {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n.dsh-github-title h2 {\n  margin: 0;\n  font-size: 20px;\n  font-weight: 600;\n}\n.dsh-github-refresh-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 14px;\n  font-size: 13px;\n  border-radius: 6px;\n  border: 1px solid var(--dsw-alias-border-l1, #444);\n  background: var(--dsw-alias-bg-secondary, #2a2a2e);\n  color: var(--dsw-alias-label-primary, #fff);\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n.dsh-github-refresh-btn:hover {\n  background: var(--dsw-alias-interactive-bg-hover, #3a3a3e);\n}\n\n/* \u6982\u89C8\u5361\u7247\u533A */\n.dsh-github-overview-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 16px;\n  margin-bottom: 24px;\n}\n.dsh-github-card {\n  padding: 16px 20px;\n  border-radius: 8px;\n  border: 1px solid var(--dsw-alias-border-l1, #333336);\n  background: var(--dsw-alias-bg-secondary, #252528);\n}\n.dsh-github-card-title {\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n  color: var(--dsw-alias-label-tertiary, #888);\n  margin-bottom: 8px;\n}\n.dsh-github-card-value {\n  font-size: 16px;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.dsh-github-badge {\n  display: inline-block;\n  font-size: 11px;\n  padding: 2px 8px;\n  border-radius: 12px;\n  font-weight: 500;\n}\n.dsh-badge-green { background: rgba(46, 160, 67, 0.2); color: #3fb950; }\n.dsh-badge-red { background: rgba(248, 81, 73, 0.2); color: #f85149; }\n.dsh-badge-yellow { background: rgba(210, 153, 34, 0.2); color: #d29922; }\n.dsh-badge-purple { background: rgba(163, 113, 247, 0.2); color: #a371f7; }\n\n/* \u6A21\u5757\u5206\u680F\u533A */\n.dsh-github-section {\n  margin-bottom: 28px;\n}\n.dsh-github-section-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 12px;\n}\n.dsh-github-section-header h3 {\n  margin: 0;\n  font-size: 15px;\n  font-weight: 600;\n}\n\n/* \u5217\u8868\u6761\u76EE */\n.dsh-github-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.dsh-github-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 16px;\n  border-radius: 6px;\n  border: 1px solid var(--dsw-alias-border-l1, #333336);\n  background: var(--dsw-alias-bg-secondary, #252528);\n  transition: border-color 0.15s ease;\n}\n.dsh-github-item:hover {\n  border-color: var(--dsw-alias-border-l2, #555);\n}\n.dsh-github-item-main {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.dsh-github-item-title {\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--dsw-alias-label-primary, #fff);\n  text-decoration: none;\n}\n.dsh-github-item-title:hover {\n  text-decoration: underline;\n}\n.dsh-github-item-meta {\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary, #8c8c8c);\n  display: flex;\n  gap: 12px;\n}\n.dsh-github-item-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.dsh-github-btn-sm {\n  font-size: 12px;\n  padding: 4px 10px;\n  border-radius: 4px;\n  border: 1px solid var(--dsw-alias-border-l1, #444);\n  background: transparent;\n  color: var(--dsw-alias-label-primary, #fff);\n  cursor: pointer;\n}\n.dsh-github-btn-sm:hover {\n  background: var(--dsw-alias-interactive-bg-hover, #333);\n}\n.dsh-github-empty {\n  padding: 24px;\n  text-align: center;\n  font-size: 13px;\n  color: var(--dsw-alias-label-tertiary, #666);\n  border: 1px dashed var(--dsw-alias-border-l1, #333);\n  border-radius: 6px;\n}\n";
